const BY_CODE = new Map(COUNTRIES.map((country) => [country.code, country]));

/** Country name for the code; the value itself if the code is not in the list. */
export function countryName(code: string): string {
  return BY_CODE.get(code)?.name ?? code;
}

/** Format shown in select lists: "Türkiye - TUR". */
export const COUNTRY_OPTIONS: ReadonlyArray<{ value: string; label: string }> = COUNTRIES.map((country) => ({
  value: country.code,
  label: `${country.name} - ${country.code}`,
}));
